g=[[0]*26 for _ in range(26)]
for r in range(26):
 if 9+r<26:g[r][9+r]=5
 if r>=2 and r-2<26:g[r][r-2]=4
 for c in (r-8,r-7):
  if 0<=c<26:g[r][c]=3
for P in range(2,27):
 buckets=[[] for _ in range(P)]
 for r in range(26):
  for c in range(26):
   if g[r][c]:buckets[(r+c)%P].append(g[r][c])
 score=sum(max(b.count(x) for x in set(b)) for b in buckets if b)
 print(P,score,sum(map(len,buckets)))

